'use strict';
(()=>{const{$,el}=UI,dialog=el('dialog',{id:'asset-delete-dialog','aria-labelledby':'asset-delete-heading'}),form=el('form',{id:'asset-delete-form'}),title=el('h2',{id:'asset-delete-heading'},'将物品移入回收站？'),description=el('p',{id:'asset-delete-description'}),warning=el('p',{class:'local-warning'},'这不是报废出库：物品及其关联流水将一起移入回收站，不再参与当前库存统计。可在页面顶部的回收站按批次恢复，不影响其他物品。回收站也仅在本浏览器，请定期下载完整备份。'),label=el('label',{},'输入“删除”确认'),input=el('input',{id:'asset-delete-word',type:'text',maxlength:'10',autocomplete:'off',required:''}),error=el('p',{id:'asset-delete-error',role:'status',class:'status error'}),actions=el('div',{class:'row'}),backup=el('button',{type:'button',id:'asset-delete-backup'},'先下载完整备份'),cancel=el('button',{type:'button',id:'asset-delete-cancel'},'取消'),confirm=el('button',{type:'submit',id:'asset-delete-confirm',class:'danger'},'移入回收站');let pending=null;label.append(input);confirm.disabled=true;actions.append(backup,cancel,confirm);form.append(title,description,warning,label,error,actions);dialog.append(form);document.body.append(dialog);
backup.onclick=()=>document.querySelector('.yj-backup-panel[data-tool=assets] .yj-backup-row button')?.click();cancel.onclick=()=>dialog.close();input.oninput=()=>confirm.disabled=input.value.trim()!=='删除';dialog.addEventListener('close',()=>{pending=null;input.value='';confirm.disabled=true});window.addEventListener('yj-asset-delete',e=>{const data=LocalAssets.state(),item=data.items.find(i=>i.id===e.detail);if(!item)return;const state=LocalAssets.ledger(data),outstanding=[...state.loans.values()].filter(l=>l.itemId===item.id).reduce((s,l)=>s+l.left,0);if(outstanding>0){$('#status').textContent='“'+item.name+'”尚有 '+outstanding+' '+item.unit+' 借出未归还，不能删除。请先处理归还。';return}pending=item.id;description.textContent='物品：'+item.name+(item.assetNo?' · 编号：'+item.assetNo:'')+'；在库 '+state.stocks.get(item.id)+' '+item.unit+'；将一并回收 '+data.entries.filter(e=>e.itemId===item.id).length+' 条关联流水。';input.value='';error.textContent='';confirm.disabled=true;dialog.showModal();cancel.focus()});form.onsubmit=e=>{e.preventDefault();if(!pending||input.value.trim()!=='删除'){error.textContent='请先输入“删除”确认。';return}try{const saved=LocalAssets.deleteItem(pending);dialog.close();if(saved)$('#status').textContent='该物品及关联流水已移入回收站，可在页面顶部按批次恢复；其他物品未改动。'}catch(err){error.textContent=err.message}};
})();

